import os
import tomllib
from typing import Any


class ConfigError(Exception):
    def __init__(self, message: str):
        super().__init__(message)


def _coerce(value: str, expected: type) -> Any:
    if expected is int:
        return int(value)
    if expected is float:
        return float(value)
    if expected is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ValueError(f"invalid bool: {value}")
    if expected is str:
        return value
    raise ValueError(f"unsupported type: {expected}")


def load_config(
    defaults: dict[str, Any],
    toml_path: str | None = None,
    env_prefix: str = "APP",
    env: dict[str, str] | None = None,
) -> dict[str, Any]:
    if env is None:
        env = dict(os.environ)

    result = dict(defaults)

    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                toml_config = tomllib.load(f)
            result.update(toml_config)
        except FileNotFoundError:
            pass

    errors: list[str] = []
    for key, value in env.items():
        env_key = f"{env_prefix}__{key.upper()}"
        if env_key not in result:
            errors.append(f"{key}: missing default")
            continue
        expected = type(result[env_key])
        try:
            coerced = _coerce(value, expected)
            result[env_key] = coerced
        except ValueError as e:
            errors.append(f"{key}: {e}")

    if errors:
        raise ConfigError("\n".join(errors))

    return result

import os
import tempfile
from envcfg import ConfigError, load_config


def test_precedence():
    defaults = {"a": 1, "b": 2}
    toml_path = tempfile.mktemp(suffix=".toml")
    with open(toml_path, "w") as f:
        f.write("a = 10\nb = 20\n")
    cfg = load_config(defaults, toml_path)
    assert cfg == {"a": 10, "b": 20}
    os.unlink(toml_path)


def test_nested_override():
    defaults = {"server": {"port": 80}}
    toml_path = tempfile.mktemp(suffix=".toml")
    with open(toml_path, "w") as f:
        f.write("server.port = 8080\n")
    cfg = load_config(defaults, toml_path)
    assert cfg == {"server": {"port": 8080}}
    os.unlink(toml_path)


def test_coercion():
    # int
    cfg = load_config({"x": 1}, env={"X": "2"})
    assert cfg == {"x": 2}
    # float
    cfg = load_config({"y": 1.5}, env={"Y": "2.5"})
    assert cfg == {"y": 2.5}
    # bool
    cfg = load_config({"z": True}, env={"Z": "false"})
    assert cfg == {"z": False}
    # str
    cfg = load_config({"s": "hi"}, env={"S": "world"})
    assert cfg == {"s": "world"}


def test_errors():
    # bad coercion
    with pytest.raises(ConfigError) as exc:
        load_config({"bad": 1}, env={"BAD": "abc"})
    assert "bad: expected int, got 'abc'" in str(exc.value)
    # missing default
    with pytest.raises(ConfigError) as exc:
        load_config({}, env={"ORPHAN": "123"})
    assert "orphan: missing default" in str(exc.value)


def test_missing_toml():
    cfg = load_config({"a": 1}, toml_path=None)
    assert cfg == {"a": 1}


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])

